import {capturePanorama,sphericalViewer} from './panorama.js';
import {roomStation,sceneFingerprint} from './interior-data.js';
import {floorRecord,layoutKey,fingerprint,planning} from './planning-data.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), $=s=>document.querySelector(s);
export function mountTourStudio(b){let jobs=[],providers=[],dispose=null,running=false,selectedProvider='cloudflare';const button=document.createElement('button');button.className='rail-btn';button.id='panorama-studio-btn';button.innerHTML='<svg><use href="#i-camera"/></svg><span>AI tour</span>';$('.rail').append(button);button.onclick=()=>open().catch(e=>b.toast(e.message));$('#modal').addEventListener('close',()=>{dispose?.();dispose=null;});
 async function api(path,options={}){const res=await fetch(path,{...options,headers:{'Content-Type':'application/json','X-Hestia-Client':'studio'}}),data=await res.json();if(!res.ok)throw Error(data.error||'Image service unavailable.');return data;}
 function ctx(){const p=b.getProject(),f=b.getFloor(),r=floorRecord(p,f.id),brief=planning(p).briefs[f.id];return {p,f,r,brief,key:layoutKey(f),briefKey:brief?fingerprint(brief):null};}
 const stale=(job,c)=>job.sceneFingerprint!==sceneFingerprint(c.p,c.f)||job.layoutRevision!==c.key||job.briefFingerprint!==c.briefKey;
 async function open(){dispose?.();dispose=null;const c=ctx();providers=(await api('/api/ai/status')).providers.filter(p=>p.panorama);jobs=(await api('/api/ai/jobs?projectId='+encodeURIComponent(c.p.id)+'&floorId='+encodeURIComponent(c.f.id))).jobs.filter(j=>j.mode==='panorama');render();}
 function render(){const c=ctx(),pilot=planning(c.p).panoramas.find(j=>j.floorId===c.f.id&&j.approved&&j.layoutKey===c.key&&j.briefKey===c.briefKey),ready=c.r.baseline&&c.brief&&c.brief.layoutKey===c.key;b.modal(`<div class="plan-lab"><span class="eyebrow">AI INTERIOR · SPHERICAL TOUR</span><h2>One room first. Then the floor.</h2><p>Generate one panorama and review the projection, seams, doors and design. Approval unlocks generation for the remaining rooms. No provider is selected automatically.</p><label class="field">Selected provider<select id="tour-provider">${providers.map(p=>`<option value="${p.id}" ${p.id===selectedProvider?'selected':''}>${esc(p.name)} · ${p.configured?'configured':'not configured'}</option>`).join('')}</select></label><p>Cloudflare requires your own account/token and has a limited free allocation. ComfyUI runs on your PC with an installed checkpoint. Requests stop on failure; Hestia never switches to a paid service.</p>${!ready?'<p class="lab-warning">Approve the original and a design brief for the current layout in Plan lab first.</p>':''}<label class="field">Room<select id="tour-room">${c.f.rooms.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')}</select></label><button id="tour-preview" class="button subtle">Preview spherical model capture (no AI)</button><button id="tour-generate" class="button" ${ready&&!running?'':'disabled'}>Generate one room panorama</button> <button id="tour-extend" class="button subtle" ${ready&&pilot&&!running?'':'disabled'}>Extend approved design across floor</button><p id="tour-progress">${running?'Generation in progress…':''}</p><p>Reference images: apply a cropped reference finish in Explore first. These two adapters accept one geometry image; they do not consume a second reference image.</p><div class="lab-report">${jobs.map(j=>`<article class="lab-card"><strong>${esc(c.f.rooms.find(r=>r.id===j.roomId)?.name||j.roomId)} · ${esc(j.status)}${stale(j,c)?' · STALE':''}</strong><p>${esc(j.providerName)} · layout ${esc(j.layoutRevision)} · ${esc(j.error||'')}</p>${j.status==='completed'?`<button data-view="${j.id}" class="button subtle">Look around 360°</button> <button data-approve="${j.id}" class="button" ${stale(j,c)?'disabled':''}>Approve this room as pilot</button>`:''}</article>`).join('')}</div><div id="tour-viewer"></div></div>`);$('#tour-provider').onchange=e=>selectedProvider=e.target.value;$('#tour-preview').onclick=()=>{try{const room=c.f.rooms.find(r=>r.id===$('#tour-room').value),position=roomStation(c.f,room);if(!position)throw Error('No valid room station.');const scene=b.getScene();scene.load(c.f,false);const source=capturePanorama(scene,position,{floor:c.f,ceilingHeight:c.brief?.ceilingHeight||2.7});b.render();dispose?.();$('#tour-viewer').innerHTML='<h3>Spherical model capture — no AI generation</h3><div class="panorama-stage"><canvas id="tour-sphere"></canvas></div>';dispose=sphericalViewer($('#tour-sphere'),source);$('#tour-viewer').scrollIntoView({block:'nearest'});}catch(e){b.render();b.toast(e.message);}};$('#tour-generate').onclick=()=>generate([$('#tour-room').value]);$('#tour-extend').onclick=()=>b.confirm('Generate the remaining room panoramas?','Each room sends a separate request to your selected provider. Account quotas apply. Hestia stops on the first failure.',()=>generate(c.f.rooms.filter(r=>!jobs.some(j=>j.roomId===r.id&&j.status==='completed'&&!stale(j,c))).map(r=>r.id)));document.querySelectorAll('[data-view]').forEach(x=>x.onclick=()=>view(x.dataset.view));document.querySelectorAll('[data-approve]').forEach(x=>x.onclick=()=>{const j=jobs.find(j=>j.id===x.dataset.approve),current=ctx();if(stale(j,current))return b.toast('This panorama is stale. Generate a current pilot.');b.mutate(p=>{p.version=2;p.planning=structuredClone(planning(p));p.planning.panoramas.push({id:j.id,floorId:current.f.id,roomId:j.roomId,layoutKey:current.key,briefKey:current.briefKey,approved:true,approvedAt:new Date().toISOString()});});render();});}
 async function generate(roomIds){if(running)return;const c=ctx(),provider=providers.find(p=>p.id===selectedProvider);if(!provider?.configured){b.toast('Configure the selected provider privately in .env and restart Hestia.');return;}if(!c.r.baseline||!c.brief||c.brief.layoutKey!==c.key)return b.toast('Approve the layout and current brief first.');running=true;render();const scene=b.getScene();try{for(const roomId of roomIds){const now=ctx();if(now.key!==c.key||now.briefKey!==c.briefKey)throw Error('Design changed. Remaining tour jobs were stopped.');const room=c.f.rooms.find(r=>r.id===roomId),station=roomStation(c.f,room);if(!station)throw Error('No valid camera station in '+room.name);scene.load(c.f,false);const source=capturePanorama(scene,station,{floor:c.f,ceilingHeight:c.brief.ceilingHeight});b.render();let job=await api('/api/ai/jobs',{method:'POST',body:JSON.stringify({projectId:c.p.id,floorId:c.f.id,roomId,provider:selectedProvider,mode:'panorama',prompt:JSON.stringify(c.brief),source,camera:{position:[...station],yaw:0,pitch:0,fov:75},layoutRevision:c.key,briefFingerprint:c.briefKey,sceneFingerprint:sceneFingerprint(c.p,c.f)})});jobs.unshift(job);render();while(['queued','running'].includes(job.status)){await new Promise(resolve=>setTimeout(resolve,1500));job=await api('/api/ai/jobs/'+job.id);jobs=jobs.map(j=>j.id===job.id?job:j);const progress=$('#tour-progress');if(progress)progress.textContent=`${room.name}: ${job.status}`;}if(job.status!=='completed')throw Error(job.error||'Panorama did not complete.');}}catch(e){b.toast(e.message);}finally{running=false;b.render();if($('#tour-progress'))render();}}
 function view(id){dispose?.();const j=jobs.find(j=>j.id===id),c=ctx(),host=$('#tour-viewer');host.innerHTML=`<h3>${esc(c.f.rooms.find(r=>r.id===j.roomId)?.name)} · drag to look around</h3><p>${stale(j,c)?'Stale design — regenerate before approval.':'Review AI geometry and seams before approving.'}</p><div class="panorama-stage"><canvas id="tour-sphere"></canvas></div><div class="chips">${jobs.filter(x=>x.status==='completed'&&!stale(x,c)).map(x=>`<button data-tour-jump="${x.id}" class="chip">${esc(c.f.rooms.find(r=>r.id===x.roomId)?.name)}</button>`).join('')}</div>`;const pos=j.camera.position,hotspots=[];for(const w of c.f.walls)for(const o of w.openings.filter(o=>o.type==='door')){const length=Math.hypot(w.x2-w.x1,w.z2-w.z1),x=w.x1+(w.x2-w.x1)*o.offset/length,z=w.z1+(w.z2-w.z1)*o.offset/length;const other=c.f.rooms.find(r=>r.id!==j.roomId&&x>=r.x-.3&&x<=r.x+r.w+.3&&z>=r.z-.3&&z<=r.z+r.d+.3),target=other&&jobs.find(v=>v.roomId===other.id&&v.status==='completed'&&!stale(v,c));if(target)hotspots.push({roomId:target.id,label:other.name,dx:x-pos[0],dz:z-pos[2]});}dispose=sphericalViewer($('#tour-sphere'),'/api/ai/jobs/'+id+'/result',{hotspots,onNavigate:view});document.querySelectorAll('[data-tour-jump]').forEach(x=>x.onclick=()=>view(x.dataset.tourJump));host.scrollIntoView({block:'nearest'});}
 return {open};
}
